#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=$ROOT/work/results/l5_online_softmax;mkdir -p "$OUT";R=$ROOT/scripts/run_memory_capped.sh;V=$ROOT/work/toolchain/conda/bin/verilator;PY=$ROOT/work/toolchain/cnn_py312/bin/python
"$ROOT/scripts/generate_fp32_primitives.sh";taskset -c 8-23 "$PY" "$ROOT/scripts/generate_online_softmax_vectors.py" --output "$OUT/vectors.memh" --manifest "$OUT/vectors.json"
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --lint-only --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL --top-module tb_fp32_online_softmax "$ROOT/work/generated/l5_fp32_primitives/HeteroFP32Primitives.sv" "$ROOT/rtl/sfu/fp32_exp2_pwl.sv" "$ROOT/rtl/sfu/fp32_online_softmax.sv" "$ROOT/tb/tb_fp32_online_softmax.sv" >"$OUT/lint.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --binary --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -j 8 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" --top-module tb_fp32_online_softmax --Mdir "$OUT/obj" -o tb "$ROOT/work/generated/l5_fp32_primitives/HeteroFP32Primitives.sv" "$ROOT/rtl/sfu/fp32_exp2_pwl.sv" "$ROOT/rtl/sfu/fp32_online_softmax.sv" "$ROOT/tb/tb_fp32_online_softmax.sv" >"$OUT/build.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$OUT/obj/tb"|tee "$OUT/tb.log";grep -q 'FP32_ONLINE_SOFTMAX_PASS tokens=10000' "$OUT/tb.log";echo L5_ONLINE_SOFTMAX_GATE_PASS
